// Headline strip: eligible patients, on a statin, not on a statin.
const root = rpt.mount('.rpt-sta-head');
if (!root) { return; }
const { esc, fmt, num, yes, pct } = rpt;
const r = rpt.rows('A')[0];
const col = (big, cls, color, label, line) => '<div>'
  + '<div class="rpt-big' + (cls ? ' ' + cls : '') + '"' + (color ? ' style="color:' + color + '"' : '') + '>' + esc(big) + '</div>'
  + '<div class="rpt-label">' + esc(label) + '</div><div class="rpt-line">' + esc(line) + '</div></div>';
if (!r) {
  root.innerHTML = '<div class="rpt-strip3">' + col('—', '', '', 'Eligible patients', rpt.NO_DATA) + col('—', '', '', 'On a statin', rpt.NO_DATA)
    + col('—', '', '', 'Not on a statin', rpt.NO_DATA) + '</div>';
  return;
}
const N = num(r.eligible_n) || 0, on = num(r.on_statin_n) || 0, off = num(r.not_on_statin_n) || 0;
const first = col(fmt(N), '', 'var(--text-primary)', 'Eligible patients', 'alive and under care');
if (!N) {
  root.innerHTML = '<div class="rpt-strip3">' + first + col('—', '', '', 'On a statin', rpt.NO_DATA) + col('—', '', '', 'Not on a statin', rpt.NO_DATA) + '</div>';
  return;
}
const flagAt = num(r.flag_below_pct);
const second = yes(r.too_few)
  ? col('Too few patients', 'rpt-few', '', 'On a statin', rpt.needAtLeast(r.min_eligible, N))
  : col(pct(r.on_statin_pct), '', yes(r.flag) ? 'var(--flag-bar)' : 'var(--controlled)', 'On a statin',
    fmt(on) + ' of ' + fmt(N) + ' eligible patients' + (flagAt !== null ? '. Under ' + pct(flagAt) + ' is flagged.' : ''));
root.innerHTML = '<div class="rpt-strip3">' + first + second
  + col(fmt(off), '', 'var(--no-visit)', 'Not on a statin', 'These patients need a review.') + '</div>';

