/* Patients to review: the overdue list pattern (.ovq-*), read-only, no download. */
.rpt-pl-title { font-size: 16px; font-weight: 500; margin: 0 0 2px; }
.rpt-pl-head { font-size: 14px; margin: 0 0 10px; }
.rpt-pl-tools { display: flex; gap: 8px; margin-bottom: 10px; }
.rpt-pl-tools input { font: inherit; color: #1c1c1c; background: #fff; border: 1px solid #d9e3ff; border-radius: 4px;
  padding: 4px 6px; height: 30px; line-height: 1.2; box-sizing: border-box; width: 280px; max-width: 100%; }
.rpt-pl-tools input:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; }
.rpt-pl-id { font-size: 12px; color: #6e7f8d; font-variant-numeric: tabular-nums; margin-top: 1px; }
.rpt-pl .rpt-table tbody td { white-space: nowrap; }
